from bisect import bisect_left


class Solution:
    def lengthOfLIS(self, nums: list[int]) -> int:
        tails = []                         # tails[k] = smallest last value of an increasing subsequence of length k + 1
        for x in nums:                     # n iterations
            i = bisect_left(tails, x)      # first tail >= x, binary search over a sorted list
            if i == len(tails):
                tails.append(x)            # x extends the longest subsequence found so far
            else:
                tails[i] = x               # x is a smaller tail for length i + 1
        return len(tails)

